<?php
declare(strict_types=1);require __DIR__.'/../api_config.php';
function d():PDO{static $d;if($d)return $d;return $d=new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
function schema():void{$d=d();$d->exec("CREATE TABLE IF NOT EXISTS barPlaylist(id int AUTO_INCREMENT PRIMARY KEY,venueId int NOT NULL,providerId varchar(255) NOT NULL,title varchar(255) NOT NULL,artist varchar(255) NOT NULL,position int NOT NULL DEFAULT 0,status varchar(20) NOT NULL DEFAULT 'QUEUED',createdAt timestamp DEFAULT CURRENT_TIMESTAMP,INDEX(venueId,status,position)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$d->exec("CREATE TABLE IF NOT EXISTS tvCommands(id int AUTO_INCREMENT PRIMARY KEY,venueId int NOT NULL,command varchar(20) NOT NULL,status varchar(20) NOT NULL DEFAULT 'PENDING',createdAt timestamp DEFAULT CURRENT_TIMESTAMP,executedAt timestamp NULL,INDEX(venueId,status,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");}
schema();session_name('tocaraul_bar');session_start();$err='';$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH);
if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=$_POST['a']??'';if($a==='login'){$code=preg_replace('/[^A-Za-z0-9]/','',$_POST['code']??'');$pix=trim($_POST['pix']??'');$q=d()->prepare('SELECT * FROM venues WHERE code=? AND pixKey=?');$q->execute([$code,$pix]);$v=$q->fetch();if(!$v)throw new RuntimeException('Bar ou chave Pix nao conferem.');session_regenerate_id(true);$_SESSION['venue']=(int)$v['id'];header('Location:/bar');exit;}if($a==='logout'){session_destroy();header('Location:/bar');exit;}if(empty($_SESSION['venue']))throw new RuntimeException('Entre novamente.');$vid=(int)$_SESSION['venue'];if($a==='pix'){d()->prepare('UPDATE venues SET pixKeyType=?,pixKey=? WHERE id=?')->execute([trim($_POST['type']),trim($_POST['pix']),$vid]);}if($a==='add'){d()->prepare("INSERT INTO barPlaylist(venueId,providerId,title,artist,position) VALUES(?,?,?,?,(SELECT n FROM(SELECT COALESCE(MAX(position),0)+1 n FROM barPlaylist WHERE venueId=?)x))")->execute([$vid,trim($_POST['video']),trim($_POST['title']),trim($_POST['artist']),$vid]);}if($a==='remove')d()->prepare('DELETE FROM barPlaylist WHERE id=? AND venueId=?')->execute([(int)$_POST['id'],$vid]);if(in_array($a,['up','down'],true)){$delta=$a==='up'?-1:1;d()->prepare('UPDATE barPlaylist SET position=GREATEST(0,position+?) WHERE id=? AND venueId=?')->execute([$delta,(int)$_POST['id'],$vid]);}if($a==='cmd'&&in_array($_POST['cmd']??'', ['PLAY','PAUSE','SKIP'],true))d()->prepare('INSERT INTO tvCommands(venueId,command) VALUES(?,?)')->execute([$vid,$_POST['cmd']]);header('Location:/bar');exit;}catch(Throwable $e){$err=$e->getMessage();}}
$v=null;$list=[];$paid=[];if(!empty($_SESSION['venue'])){$q=d()->prepare('SELECT * FROM venues WHERE id=?');$q->execute([(int)$_SESSION['venue']]);$v=$q->fetch();$q=d()->prepare("SELECT * FROM barPlaylist WHERE venueId=? AND status='QUEUED' ORDER BY position,id");$q->execute([(int)$_SESSION['venue']]);$list=$q->fetchAll();$q=d()->prepare("SELECT title,artist,tableCode,status FROM songRequests WHERE venueId=? AND status IN('QUEUED','PLAYING') ORDER BY status='PLAYING' DESC,queuePosition");$q->execute([(int)$_SESSION['venue']]);$paid=$q->fetchAll();}
function h($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}?><!doctype html><meta name=viewport content="width=device-width,initial-scale=1"><title>Painel do Bar · TocaRaul</title><style>*{box-sizing:border-box}body{margin:0;background:#090909;color:#fff;font:15px system-ui}.w{max-width:900px;margin:auto;padding:22px}.logo{color:#fc0;font-size:28px;font-weight:900}.c{background:#141414;border:1px solid #292929;border-radius:18px;padding:18px;margin:16px 0}input,select,button{padding:12px;border-radius:11px;border:1px solid #333;background:#080808;color:#fff}input{width:100%;margin:5px 0 10px}button{background:#fc0;color:#000;font-weight:800;cursor:pointer}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.item{padding:11px;border-bottom:1px solid #292929}.paid{border-left:4px solid #fc0;padding-left:10px}.muted{color:#999}.err{color:#f88}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style><div class=w><div class=logo>TocaRaul · Painel do Bar</div><?php if($err):?><p class=err><?=h($err)?></p><?php endif;?><?php if(!$v):?><div class=c><h2>Entrar</h2><p class=muted>Use o codigo do bar e a chave Pix cadastrada.</p><form method=post><input type=hidden name=a value=login><label>Codigo do bar</label><input name=code required><label>Chave Pix</label><input name=pix required><button>Entrar</button></form></div><?php else:?><div class=c><div class=row><h2 style="flex:1"><?=h($v['name'])?></h2><form method=post><input type=hidden name=a value=logout><button>Sair</button></form></div><p>Codigo: <b><?=h($v['code'])?></b></p></div><div class=grid><div class=c><h2>Controle da TV</h2><div class=row><?php foreach(['PLAY'=>'▶ Tocar','PAUSE'=>'⏸ Pausar','SKIP'=>'⏭ Pular'] as $x=>$label):?><form method=post><input type=hidden name=a value=cmd><input type=hidden name=cmd value=<?=$x?>><button><?=$label?></button></form><?php endforeach;?></div><h3>Pedidos pagos — prioridade</h3><?php if(!$paid):?><p class=muted>Nenhum pedido pago aguardando.</p><?php endif;foreach($paid as $p):?><div class="item paid"><b><?=h($p['title'])?></b> · <?=h($p['artist'])?> <span class=muted><?=h($p['tableCode'])?> · <?=h($p['status'])?></span></div><?php endforeach;?></div><div class=c><h2>Recebimento</h2><p class=muted>O bar pode usar chave Pix de qualquer banco.</p><form method=post><input type=hidden name=a value=pix><select name=type><option>CPF</option><option>CNPJ</option><option>EMAIL</option><option>TELEFONE</option><option>ALEATORIA</option></select><input name=pix value="<?=h($v['pixKey'])?>" required><button>Salvar chave Pix</button></form></div></div><div class=c><h2>Playlist do bar</h2><p class=muted>Ela toca somente quando nao houver pedido pago. Um pedido comprado assume a proxima posicao automaticamente.</p><form method=post class=grid><input type=hidden name=a value=add><div><label>ID do video YouTube</label><input name=video maxlength=11 required></div><div><label>Titulo</label><input name=title required></div><div><label>Artista</label><input name=artist required></div><div style="align-self:end"><button>Adicionar</button></div></form><?php foreach($list as $i):?><div class="item row"><div style="flex:1"><b><?=h($i['title'])?></b><div class=muted><?=h($i['artist'])?></div></div><?php foreach(['up'=>'↑','down'=>'↓','remove'=>'×'] as $a=>$label):?><form method=post><input type=hidden name=a value=<?=$a?>><input type=hidden name=id value=<?=(int)$i['id']?>><button><?=$label?></button></form><?php endforeach;?></div><?php endforeach;?></div><?php endif;?></div>